import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"属性与技能接入","description":"","frontmatter":{},"headers":[],"relativePath":"modules/accessory/integration.md","filePath":"modules/accessory/integration.md","lastUpdated":0}`),a={name:`modules/accessory/integration.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="属性与技能接入" tabindex="-1">属性与技能接入 <a class="header-anchor" href="#属性与技能接入" aria-label="Permalink to “属性与技能接入”">​</a></h1><p>饰品的属性和技能不是 EmakiAccessory 自己算的, 而是注册到 EmakiAttribute 与 EmakiSkills 的对外接入点上. 这两个模块是软依赖, 缺失时对应的那一半自动失效, 饰品栏本身照常可用</p><h2 id="属性接入-emakiattribute" tabindex="-1">属性接入 EmakiAttribute <a class="header-anchor" href="#属性接入-emakiattribute" aria-label="Permalink to “属性接入 EmakiAttribute”">​</a></h2><p>EmakiAccessory 向 EmakiAttribute 注册一个<strong>贡献提供者</strong> (提供者 id <code>emakiaccessory:accessories</code>, 优先级 100), 把饰品带来的属性作为独立来源汇入战斗快照. 它不注册自定义装备槽位, 也不写入玩家身上的原版属性</p><p>上报的来源 id:</p><table tabindex="0"><thead><tr><th>来源 id</th><th>含义</th></tr></thead><tbody><tr><td><code>emakiaccessory:accessory</code></td><td>单件饰品自身的属性</td></tr><tr><td><code>emakiaccessory:set</code></td><td>饰品套装的加成</td></tr></tbody></table><p>属性值通过 EmakiAttribute 的 <code>AttributeCatalog#itemSnapshot</code> 读取 -- <strong>与装备路径同一个解析器</strong>. 因此一件饰品和一顶数据相同的头盔产出完全相同的数值, 父属性展开与范围伴生键 (range spread companion keys) 一并生效</p><p>范围伴生键与普通键一样参与求和, 否则带范围的饰品会只保留下界而丢掉浮动区间</p><p>EmakiAttribute 不可用时 (<code>EmakiAttributeApi.status().usable()</code> 为 false) 不注册提供者, 饰品属性整体不生效</p><h2 id="技能接入-emakiskills" tabindex="-1">技能接入 EmakiSkills <a class="header-anchor" href="#技能接入-emakiskills" aria-label="Permalink to “技能接入 EmakiSkills”">​</a></h2><p>EmakiAccessory 向 EmakiSkills 注册一个<strong>技能来源</strong> (提供者 id <code>accessories</code>). 饰品上的装备技能载荷由 <code>AccessorySkillPayloadCodec.read</code> 读取, 与 Item / Forge / Gem / Strengthen 写入的是同一套 PDC 契约</p><p>饰品套装 <code>thresholds[].effects[].es_skills</code> 里列出的技能也经由同一条路径生效</p><p>技能条目的来源槽字段: 单件饰品技能用<strong>槽位实例 id</strong>, 套装技能用 <code>set:&lt;套装id&gt;</code></p><p>未安装 EmakiSkills 时模块照常启用: 技能集成类由 <code>AccessoryProviderRegistrar</code> 按类名 <code>emaki.jiuwu.craft.accessory.provider.AccessorySkillsProviderIntegration</code> 反射加载, 只有在 <code>EmakiSkills</code> 已启用时才会加载它, 因此 EmakiSkills 缺失不会造成类加载失败, 只是没有技能来源</p><h2 id="槽位限制判据" tabindex="-1">槽位限制判据 <a class="header-anchor" href="#槽位限制判据" aria-label="Permalink to “槽位限制判据”">​</a></h2><p>饰品栏只接受<strong>显式声明了饰品槽</strong>的物品. 物品自带的声明来源只有一个:</p><ol><li>EmakiItem 物品定义里 <code>effects</code> 的 <code>type: &quot;accessory_slot&quot;</code>, 由 EmakiItem 写入物品 PDC 的 <code>emakiitem:accessory_slots</code> (字符串列表)</li></ol><p>在此基础上, <code>config.yml</code> 里的 <code>slot_sources.pdc</code> 与 <code>slot_sources.lore</code> 是服主显式开启的追加来源, 默认都关闭; 开启后与物品自带声明取并集 (any-of)</p><p>EmakiAttribute 载荷的 <code>active_slot</code> 元数据与 EmakiSkills 载荷的 <code>active_slot</code> <strong>不再</strong>参与饰品栏判定. 旧行为下物品未指定槽位时会被写成 <code>all</code>, 于是任何 EmakiItem 物品都能放进任意饰品格; 现在这类物品会因为没有任何 <code>accessory_slots</code> 声明而被拒绝. 属性与技能贡献沿用同一判据, 因此声明不匹配的格既放不进, 也不产生贡献</p><p>匹配规则: 声明集合里<strong>只要有任意一条命中当前格</strong>就通过 (any-of)</p><table tabindex="0"><thead><tr><th>物品声明的槽位</th><th>结果</th></tr></thead><tbody><tr><td>部位 id, 如 <code>ring</code></td><td>该部位的任意一格生效</td></tr><tr><td>槽位实例 id, 如 <code>ring_1</code></td><td>只有这一格生效</td></tr><tr><td>其他值 (如 <code>hand</code>, <code>main_hand</code> 等装备槽名)</td><td>命中不了任何饰品槽, 等同未声明</td></tr><tr><td>没有 <code>accessory_slots</code> 键 (且追加来源也没读到)</td><td>拒绝放入, 提示 <code>gui.not_declared</code>, 贡献被整体丢弃</td></tr></tbody></table><p>容器行为上的两道保险:</p><ul><li>放入时判据不通过即拒绝, 光标物品原样留在光标上, 不会进入槽位;</li><li>关闭界面时对<strong>全部页</strong>做一次校验, 把&quot;已不在槽位声明内&quot;的物品取出并退回玩家背包 (背包放不下就掉在脚下), 逐件提示 <code>gui.invalid_returned</code>. 孤儿格 (该页已不再声明的槽位) 不受影响, 仍按孤儿取回流程处理</li></ul><p>如果装备侧的判据规则将来发生变化, 饰品侧这份实现需要同步评估</p><h2 id="条件门控" tabindex="-1">条件门控 <a class="header-anchor" href="#条件门控" aria-label="Permalink to “条件门控”">​</a></h2><p>饰品栏中的饰品会按定义自己的 <code>condition</code> 做门控: 条件不满足时, 该饰品的属性, 技能与套装件数<strong>全部</strong>停止参与贡献, 物品仍留在槽内</p><p>判据走 EmakiItemApi 的静默查询 <code>ItemCatalog#conditionSatisfied(player, itemStack)</code> -- 它是 <code>conditionPasses</code> 的静默版本, 不执行 <code>on_pass</code>/<code>on_fail</code> 动作, 不发 <code>on_fail.message</code>, 因此可以在贡献重算与界面渲染里反复求值. 触发上下文与装备路径的贡献门控一致, 都是 <code>contribution</code></p><p>求值时机是<strong>贡献重算</strong>: GUI 编辑, 页切换, 数据加载完成, reload, <code>/eacc retrieve</code>, 死亡掉落, 耐久扣满. 也就是说条件本身 (等级, 职业, 占位符) 变化后不会立刻反映到饰品栏, 要到下一次重算才生效; 这与装备路径&quot;每次收集实时求值&quot;不同</p><p>EmakiItem 未安装, 玩家离线, 调用线程不是玩家 owner 线程或定义无法解析时, 查询返回失败, 饰品侧按&quot;条件满足&quot;处理 (即不门控), 避免因为依赖缺失误伤饰品</p><p>界面上的状态标识: 条件不满足的饰品在饰品栏里额外显示一行 <code>gui.condition_unmet</code> 提示; 该行只出现在界面投影中, 不会写回物品本身</p><h2 id="耐久度门控" tabindex="-1">耐久度门控 <a class="header-anchor" href="#耐久度门控" aria-label="Permalink to “耐久度门控”">​</a></h2><p><code>durability.enabled</code> 打开后, 生效页上的饰品会在玩家受伤时按 <code>durability.damage_per_hit</code> 扣除耐久; 扣满后该饰品的属性, 技能与套装件数全部停止生效, 物品保留在槽内并显示 <code>gui.durability_broken</code> 标识. 判据与配置细节见<a href="./configuration.html">主配置</a>与<a href="./parts.html">部位定义</a></p><h2 id="重算时机" tabindex="-1">重算时机 <a class="header-anchor" href="#重算时机" aria-label="Permalink to “重算时机”">​</a></h2><p>贡献快照在饰品内容发生变化时重算: GUI 编辑, 数据加载完成, reload, <code>/eacc retrieve</code> 取回, 死亡掉落清空生效页. 仅打开窗口不改数据, 不触发重算. 条件门控与耐久门控都在这条路径上求值</p><p>重算<strong>不在提供者回调里进行</strong>. EmakiAttribute 的战斗快照收集器会在计算自己的缓存签名时调用贡献提供者, 也就是每次读取战斗快照都会调用一次; 把 PDC 解析放在那里等于把物品反序列化搬到战斗热路径上</p><h2 id="线程要求" tabindex="-1">线程要求 <a class="header-anchor" href="#线程要求" aria-label="Permalink to “线程要求”">​</a></h2><p>重算必须在持有这些物品的玩家的 owner 线程执行: 属性解析器会把结果写回物品 PDC 作为缓存, off-thread 执行不安全. 条件门控的查询同样要求玩家 owner 线程, 不满足时按&quot;条件满足&quot;处理</p><h2 id="缺失模块时的行为" tabindex="-1">缺失模块时的行为 <a class="header-anchor" href="#缺失模块时的行为" aria-label="Permalink to “缺失模块时的行为”">​</a></h2><table tabindex="0"><thead><tr><th>缺失的模块</th><th>影响</th></tr></thead><tbody><tr><td>EmakiAttribute</td><td>不注册属性提供者, 饰品不提供属性; 饰品栏与套装件数统计照常工作 (套装件数只依赖 EmakiItem)</td></tr><tr><td>EmakiSkills</td><td>不注册技能来源, 饰品与套装的技能都不提供; 其余功能照常</td></tr><tr><td>EmakiItem</td><td>物品不再带 <code>accessory_slots</code> 声明 (已有物品上的该键仍在), 因此除 <code>slot_sources</code> 追加来源命中的物品外都无法放入; 条件门控整体跳过 (按满足处理); <code>unique</code> 去重回退为原版材质判定; 依赖 <code>pieces[].item</code> 的饰品套装整体不生效 (件数恒为 0)</td></tr><tr><td>PlaceholderAPI</td><td>文本中的 PAPI 占位符不再替换, 原样输出</td></tr></tbody></table><p>EmakiAccessory 本身<strong>没有</strong> PlaceholderAPI 扩展, 不对外提供 <code>%emakiaccessory_*%</code> 占位符; 它只是可选地消费 PlaceholderAPI. 本模块也<strong>没有</strong>向 CoreLib 动作注册表注册任何动作 (模块内唯一的 <code>super(&quot;accessory&quot;, …)</code> 是配置预检贡献者的模块 id, 不是动作段)</p>`,40)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};